package com.kisa.naver;
import android.app.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.net.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.lang.ref.WeakReference;import java.util.concurrent.*;
/** Watches Tmap from the independent Naver process, even when Tmap dies. */
public final class RecordingWatchdog {
 static Application app;static final RecordingPolicy policy=new RecordingPolicy();static final Handler MAIN=new Handler(Looper.getMainLooper());static WeakReference<Activity> activity=new WeakReference<>(null);static WeakReference<TextView> banner=new WeakReference<>(null);static String displayed="",recordedToken="";static final int NOTICE=83012;
 public static synchronized void init(Application a){if(app!=null)return;app=a;MAIN.post(()->{try{((NotificationManager)app.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(NOTICE);}catch(Exception ignored){}});policy.arm(a.getSharedPreferences("tmap_record_watch",0).getString("expected",""),SystemClock.elapsedRealtime());ScheduledExecutorService timer=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"TmapRecordingWatch");t.setDaemon(true);return t;});timer.scheduleWithFixedDelay(()->poll(),500,2000,TimeUnit.MILLISECONDS);}
 public static void resumed(Activity a){activity=new WeakReference<>(a);render();}
 static void expect(String trip){synchronized(policy){policy.arm(trip,SystemClock.elapsedRealtime());}}
 public static void paused(Activity a){if(activity.get()==a)activity.clear();}
 static void poll(){synchronized(policy){try(java.net.Socket socket=new java.net.Socket()){socket.connect(new java.net.InetSocketAddress("127.0.0.1",18316),1500);socket.setSoTimeout(1500);ByteArrayOutputStream bytes=new ByteArrayOutputStream();int ch;InputStream input=socket.getInputStream();while((ch=input.read())!=-1&&ch!='\n'){if(bytes.size()>4096)throw new IOException("Health size");bytes.write(ch);}JSONObject row=new JSONObject(bytes.toString("UTF-8"));if(!"com.skt.tmap.ku".equals(row.optString("package")))throw new IOException("Not Tmap health");CompanionMode.health(row);policy.health(row.optString("token"),row.optString("status"),row.optString("drive_mode"),row.optBoolean("route"),row.optLong("main_age_ms",-1),row.optLong("guidance_age_ms",-1),row.optLong("started_age_ms",-1),SystemClock.elapsedRealtime());}catch(Exception unavailable){policy.missing(SystemClock.elapsedRealtime());}com.kisa.transport.TransientNotice.update(app,policy.expected,policy.message);app.getSharedPreferences("tmap_record_watch",0).edit().putString("expected",policy.expected).apply();String next=policy.message;if(!next.equals(displayed)||!policy.expected.equals(recordedToken)){recordedToken=policy.expected;displayed=next;diagnostic(next);}}}
 static void diagnostic(String message){try{File dir=new File(app.getExternalFilesDir(null),"tmap_record_watch");dir.mkdirs();JSONObject row=new JSONObject().put("timestamp_ms",System.currentTimeMillis()).put("message",message).put("monitoring",!policy.expected.isEmpty());java.nio.file.Files.write(new File(dir,"status.json").toPath(),row.toString(2).getBytes("UTF-8"));android.util.Log.i("TmapRecordWatch",row.toString());}catch(Exception ignored){}}
 static int dp(Activity a,int value){return Math.round(value*a.getResources().getDisplayMetrics().density);}
 static void render(){com.kisa.transport.TransientNotice.refresh();}
 private RecordingWatchdog(){}
}
